#define ENG_IDLE(mach, densalt) (table2d(T2r_34, 6, T2c_34, 8, T2d_34, (mach), (densalt)))
#define ENG_MIL(mach, densalt)  (table2d(T2r_35, 8, T2c_35, 8, T2d_35, (mach), (densalt)))
