#define FCS_AIL_SPEED(mach) (table1d(T1x_37, T1y_37, 2, (mach)))
#define FCS_ELEV_SCHED(alpha) (table1d(T1x_38, T1y_38, 5, (alpha)))
#define FCS_YAW_RATE(vg) (table1d(T1x_39, T1y_39, 3, (vg)))
#define KCLGE(hb) (table1d(T1x_40, T1y_40, 13, (hb)))

// ---------------- 공력 40함수 평탄화 ----------------
HOSTDEV void f16_aero(
    double qbar, double alpha, double beta, double mach,
    double bi2vel, double ci2vel, double kclge,
    double p_aero, double q_aero, double r_aero,
    double ail_pos, double elev_pos, double rud_pos, double lef_pos,
    double flap_mix, double sb_pos, double gear_pos,
    double* DRAG, double* SIDE, double* LIFT,
    double* ROLL, double* PITCH, double* YAW) {
  double s;
  // ===== DRAG =====
  s = 0.0;
  s += qbar * 300.0 * table2d(T2r_0, 12, T2c_0, 5, T2d_0, alpha, elev_pos);   // aero/coefficient/CDDh
  s += qbar * 300.0 * table1d(T1x_1, T1y_1, 4, mach);   // aero/coefficient/CDmach
  s += qbar * 300.0 * lef_pos * table1d(T1x_2, T1y_2, 12, alpha);   // aero/coefficient/CDDlef
  s += qbar * 300.0 * flap_mix * 0.08;   // aero/coefficient/CDDflaps
  s += qbar * 300.0 * gear_pos * 0.027;   // aero/coefficient/CDgear
  s += qbar * 300.0 * sb_pos * table1d(T1x_3, T1y_3, 12, alpha);   // aero/coefficient/CDDsb
  s += qbar * 300.0 * q_aero * ci2vel * table1d(T1x_4, T1y_4, 12, alpha);   // aero/coefficient/CDq
  s += qbar * 300.0 * q_aero * ci2vel * lef_pos * table1d(T1x_5, T1y_5, 12, alpha);   // aero/coefficient/CDq_Dlef
  *DRAG = s;
  // ===== SIDE =====
  s = 0.0;
  s += qbar * 300.0 * beta * -1.146;   // aero/coefficient/CYb
  s += qbar * 300.0 * beta * table1d(T1x_6, T1y_6, 3, mach);   // aero/coefficient/CYb_M
  s += qbar * 300.0 * ail_pos * -0.0226;   // aero/coefficient/CYDa
  s += qbar * 300.0 * rud_pos * 0.086;   // aero/coefficient/CYdr
  s += qbar * 300.0 * bi2vel * p_aero * table1d(T1x_7, T1y_7, 12, alpha);   // aero/coefficient/CYp
  s += qbar * 300.0 * bi2vel * r_aero * table1d(T1x_8, T1y_8, 12, alpha);   // aero/coefficient/CYr
  *SIDE = s;
  // ===== LIFT =====
  s = 0.0;
  s += qbar * 300.0 * kclge * table2d(T2r_9, 12, T2c_9, 5, T2d_9, alpha, elev_pos);   // aero/coefficient/CLDh
  s += qbar * 300.0 * lef_pos * kclge * table1d(T1x_10, T1y_10, 12, alpha);   // aero/coefficient/CLDlef
  s += qbar * 300.0 * flap_mix * kclge * 0.35;   // aero/coefficient/CLDflaps
  s += qbar * 300.0 * kclge * sb_pos * table1d(T1x_11, T1y_11, 12, alpha);   // aero/coefficient/CLDsb
  s += qbar * 300.0 * q_aero * kclge * ci2vel * table1d(T1x_12, T1y_12, 12, alpha);   // aero/coefficient/CLq
  s += qbar * 300.0 * q_aero * ci2vel * sb_pos * table1d(T1x_13, T1y_13, 12, alpha);   // aero/coefficient/CLq_Dsb
  *LIFT = s;
  // ===== ROLL =====
  s = 0.0;
  s += qbar * 300.0 * 30.0 * table2d(T2r_14, 12, T2c_14, 13, T2d_14, alpha, beta);   // aero/coefficient/Clb
  s += qbar * 300.0 * 30.0 * beta * table1d(T1x_15, T1y_15, 6, mach);   // aero/coefficient/Clb_M
  s += qbar * 300.0 * 30.0 * bi2vel * p_aero * table1d(T1x_16, T1y_16, 12, alpha);   // aero/coefficient/Clp
  s += qbar * 300.0 * 30.0 * bi2vel * r_aero * table1d(T1x_17, T1y_17, 12, alpha);   // aero/coefficient/Clr
  s += qbar * 300.0 * 30.0 * ail_pos * table2d(T2r_18, 12, T2c_18, 7, T2d_18, alpha, beta);   // aero/coefficient/Clda
  s += qbar * 300.0 * 30.0 * alpha * ail_pos * table1d(T1x_19, T1y_19, 3, mach);   // aero/coefficient/Clda_M
  s += qbar * 300.0 * 30.0 * alpha * rud_pos * table1d(T1x_20, T1y_20, 2, mach);   // aero/coefficient/Cldr_M
  s += qbar * 300.0 * 30.0 * rud_pos * table2d(T2r_21, 12, T2c_21, 7, T2d_21, alpha, beta);   // aero/coefficient/Cldr
  *ROLL = s;
  // ===== PITCH =====
  s = 0.0;
  s += qbar * 300.0 * 11.32 * table2d(T2r_22, 12, T2c_22, 5, T2d_22, alpha, elev_pos);   // aero/coefficient/CmDh
  s += qbar * 300.0 * 11.32 * alpha * table1d(T1x_23, T1y_23, 6, mach);   // aero/coefficient/Cma_M
  s += qbar * 300.0 * 11.32 * sb_pos * table1d(T1x_24, T1y_24, 12, alpha);   // aero/coefficient/CmDsb
  s += qbar * 300.0 * 11.32 * ci2vel * q_aero * table1d(T1x_25, T1y_25, 12, alpha);   // aero/coefficient/Cmq
  *PITCH = s;
  // ===== YAW =====
  s = 0.0;
  s += qbar * 300.0 * 30.0 * table2d(T2r_26, 12, T2c_26, 13, T2d_26, alpha, beta);   // aero/coefficient/Cnb
  s += qbar * 300.0 * 30.0 * beta * table1d(T1x_27, T1y_27, 8, mach);   // aero/coefficient/Cnb_M
  s += qbar * 300.0 * 30.0 * bi2vel * p_aero * table1d(T1x_28, T1y_28, 12, alpha);   // aero/coefficient/Cnp
  s += qbar * 300.0 * 30.0 * bi2vel * r_aero * table1d(T1x_29, T1y_29, 12, alpha);   // aero/coefficient/Cnr
  s += qbar * 300.0 * 30.0 * ail_pos * table1d(T1x_30, T1y_30, 6, mach);   // aero/coefficient/Cnda_M
  s += qbar * 300.0 * 30.0 * ail_pos * table2d(T2r_31, 12, T2c_31, 7, T2d_31, alpha, beta);   // aero/coefficient/Cnda
  s += qbar * 300.0 * 30.0 * rud_pos * table2d(T2r_32, 12, T2c_32, 7, T2d_32, alpha, beta);   // aero/coefficient/Cndr
  s += qbar * 300.0 * 30.0 * alpha * rud_pos * table1d(T1x_33, T1y_33, 3, mach);   // aero/coefficient/Cndr_M
  *YAW = s;
}

